import java.util.Scanner;

public class JavaApplication1 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        s = sc.nextLine();

        // Use regex to extract content inside parentheses
        String inside = s.replaceAll("[^()]*\\([^)]*\\)", " ")
                        .replaceAll("[^()]*", " ")
                        .replaceAll("\\([^)]*\\)", " ")
                        .replaceAll("[^()]*", " ");

        // Extract content inside parentheses more reliably
        StringBuilder insideBuilder = new StringBuilder();
        int depth = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                depth++;
            } else if (c == ')') {
                depth--;
                insideBuilder.append(' ');
            } else if (depth > 0) {
                insideBuilder.append(c);
            }
        }

        // Remove parentheses and their contents
        String outside = s.replaceAll("\\([^)]*\\)", " ");

        // Normalize whitespace
        String outClean = outside.replaceAll("\\s+", " ").trim();
        String inClean = insideBuilder.toString().replaceAll("\\s+", " ").trim();

        // Calculate max length and word count
        int maxLen = 0;
        int wordCount = 0;

        if (!outClean.isEmpty()) {
            String[] parts = outClean.split(" ");
            for (String part : parts) {
                if (part.length() > maxLen) {
                    maxLen = part.length();
                }
            }
        }

        if (!inClean.isEmpty()) {
            wordCount = inClean.split(" ").length;
        }

        System.out.println(maxLen + " " + wordCount);
    }
}
